    ['staff', 80, 93],
    ['potion', 40, 49],
  ])('a plain %s has base premium %d', (type, _base, expected) => {
    expect(quote({ yearsWithMHPCO: 0 }, [{ type }], 0).premium).toBe(expected);
  });
});

