describe('policy-wide modifiers', () => {
  test('a customer of exactly two years receives the loyalty discount', () => {
    // 100 base − 20 loyalty + 10 first insurance + 5 fee
    expect(quote({ yearsWithMHPCO: 2 }, [{ type: 'sword' }], 0).premium).toBe(95);
