    expect(premiumBeforePolicyModifiers([{ type: 'sword', enchantment: 5 }])).toBe(130);
  });

  test('enchantment of 4 adds no high-enchantment surcharge', () => {
    expect(premiumBeforePolicyModifiers([{ type: 'sword', enchantment: 4 }])).toBe(100);
